package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;import org.json.*;
public final class SourceRoadGpuInstrumentation extends SceneGpuInstrumentation {
 boolean[] correctedCommands;int correctedVisibleSamples;
 @Override int[] expected(NativeSceneSnapshot scene,NativeSceneDrawPlan plan,float[][] sources,double x,double y){lastSample="";int[] result=super.expected(scene,plan,sources,x,y);if(result!=null)for(int i=0;i<correctedCommands.length;i++)if(correctedCommands[i]&&lastSample.startsWith("command="+i+" ")){correctedVisibleSamples++;break;}return result;}

 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{
  byte[] raw=Files.readAllBytes(new File(getTargetContext().getFilesDir(),"source-road-scene-whole.nab").toPath());NativeSceneSnapshot scene=new NativeSceneSnapshot(raw);NativeSceneDrawPlan plan=new NativeSceneDrawPlan(scene.geometry(0));int indexed=0;for(int i=0;i<plan.count();i++)if(plan.draw(i).indexed)indexed++;ok(indexed>=1,"Source road must be indexed");
  NativeWorldScene world=new NativeWorldScene(scene.geometry(0));int corrected=0;for(int i=0;i<world.surfaceCount();i++)if(world.surface(i).mode==9||world.surface(i).mode==10)corrected++;ok(corrected==1,"One raw-camera road required");int crossings=0;for(int si=0;si<world.surfaceCount();si++){NativeWorldScene.Surface source=world.surface(si);if(source.sourceCamera()==null)continue;NativeRoadCamera camera=new NativeRoadCamera(source.sourceCamera());java.nio.ByteBuffer points=source.vertices();double[] depths=new double[source.corners];for(int i=0;i<depths.length;i++)depths[i]=camera.point(new double[]{points.getDouble(i*24),points.getDouble(i*24+8),points.getDouble(i*24+16)})[2];for(int i=0;i<depths.length;i++)if((depths[i]<64)!=(depths[(i+1)%depths.length]<64))crossings++;}correctedCommands=new boolean[plan.count()];for(int i=0;i<plan.count();i++){NativeSceneDrawPlan.Draw draw=plan.draw(i);correctedCommands[i]=!draw.model&&(world.surface(draw.index).mode==9||world.surface(draw.index).mode==10);}startGl();live=true;String small=render(scene,240,160,240,160,"source-road-scene-240.png",false),large=render(scene,3840,2160,3240,2160,"source-road-scene-4k.png",false);endGl();live=false;startGl();live=true;ok(render(scene,240,160,240,160,null,false).equals(small),"Indexed context changed pixels");
  ok(correctedVisibleSamples>0,"No visible corrected-road samples");JSONObject report=new JSONObject();report.put("visible_corrected_road_sample_evaluations",correctedVisibleSamples);report.put("result","PASS_ANDROID_SOURCE_ROAD_GLES");report.put("source_commands",plan.count());report.put("near_crossing_edges",crossings);report.put("corrected_roads",corrected);report.put("indexed_commands",indexed);report.put("renderer",renderer);report.put("api",Build.VERSION.SDK_INT);report.put("source_pixel_checks",checks);report.put("zero_index_evaluations",zeroChecks);report.put("wall_skip_evaluations",wallSkipEvaluations);report.put("native_rgba_sha256",small);report.put("four_k_frame_sha256",large);report.put("synthetic_materials",true);report.put("per_row_palette_variants",160);report.put("context_recreated",true);report.put("full_scene",false);report.put("real_time_pacing",false);try(FileOutputStream out=getTargetContext().openFileOutput("source-road-scene-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){android.util.Log.e("NFSUGSceneGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
